import java.util.Locale

fun main() {
    val sales = intArrayOf(120, 135, 98, 143, 160, 152, 171, 149, 188, 176)
    val window = 3
    for (i in window - 1 until sales.size) {
        val sum = (i - window + 1..i).sumOf { sales[it] }
        val average = sum.toDouble() / window
        println("day %d: %.2f".format(Locale.ROOT, i + 1, average))
    }
}
